import { queryExecutionClient } from "@dynatrace-sdk/client-query";
import { executionsClient } from "@dynatrace-sdk/client-automation";

export default async function ({ execution_id }) {
  const execution = await executionsClient.getExecution({ id: execution_id });
  const event = execution.params?.event;
  const releaseVersion = event["release.version"];
  console.log("Fetching eval result for release.version:", releaseVersion);

  const dql = 'fetch bizevents | filter event.type == "ai_agent.eval.experiment_completed" | filter `release.version` == "' + releaseVersion + '" | limit 1';

  const result = await queryExecutionClient.queryExecute({
    body: {
      query: dql,
      requestTimeoutMilliseconds: 15000,
      maxResultRecords: 1
    }
  });

  const record = result.result?.records?.[0] ?? null;
  console.log("Eval record:", JSON.stringify(record));
  return record;
}

export default async function ({ execution_id }) {
  console.log("SRG stub — returning pass unconditionally");
  return { validation_status: "pass", reason: "stub — operational SRG not yet configured" };
}

import { executionsClient } from "@dynatrace-sdk/client-automation";
import { credentialVaultClient } from "@dynatrace-sdk/client-platform-management";

export default async function ({ execution_id }) {
  const execution = await executionsClient.getExecution({ id: execution_id });
  const event = execution.params?.event;

  const releaseVersion = event["release.version"];
  const proceedUrl     = event["jenkins.proceed.url"];
  const abortUrl       = event["jenkins.abort.url"];

  const evalRecord = await executionsClient.getTaskExecutionResult({ executionId: execution_id, id: "fetch_eval_result" });
  const srgResult  = await executionsClient.getTaskExecutionResult({ executionId: execution_id, id: "srg_check_stub" });

  const evalPassed = evalRecord?.["eval.overall.passed"] === true;
  const srgPassed  = srgResult?.validation_status === "pass";
  const passed     = evalPassed && srgPassed;

  console.log("release.version     :", releaseVersion);
  console.log("eval.overall.passed :", evalPassed, "| avg_score:", evalRecord?.["eval.overall.avg_score"]);
  console.log("srg.passed          :", srgPassed);
  console.log("Final decision      :", passed ? "PROCEED" : "ABORT");

  const cred = await credentialVaultClient.getCredential({ id: "CREDENTIALS_VAULT-7EC7D48C59CAF90C" });
  const basicAuth = btoa(cred.username + ":" + cred.password);
  const targetUrl = passed ? proceedUrl : abortUrl;

  console.log("Calling Jenkins:", targetUrl);
  const response = await fetch(targetUrl, {
    method: "POST",
    headers: { "Authorization": "Basic " + basicAuth }
  });

  console.log("Jenkins response:", response.status);
  return { passed: passed, action: passed ? "proceed" : "abort", jenkinsStatus: response.status };
}
